      "macos" => ["markdown-preview-macos", "plugins/markdown-preview.nvim/app/bin/markdown-preview-macos"],
      "linux" => ["markdown-preview-linux", "plugins/markdown-preview.nvim/app/bin/markdown-preview-linux"],
